// DocumentReferenceCardExtended.jsx
import React, { useEffect, useState } from "react";
import { Modal } from "react-bootstrap";
import styles from "./GenericFHIRViewerModal.module.css";
import drstyles from "./DocumentReferenceCardExtended.module.css";
import FemalePatient from "../assets/scanner-female.png";
import MalePatient from "../assets/scanner-male.png";
import FemaleProvider from "../assets/Doctor_Female.jpg";
import MaleProvider from "../assets/Doctor_Male_96.png";
import DefaultProvider from "../assets/Doctor_Male_96.png";
import PDFViewer from "../utils/PDFViewer";
import { useSelector, useDispatch, useStore } from "react-redux";
import { fetchPatientByReference } from "../services/patientService";
import { fetchProviderByReference } from "../services/providerService";
import { fetchOrganizationByReference } from "../services/organizationService";
import DefaultOrg from "../assets/world-health.png";
import { fetchAttachment } from "../utils/fetchAttachment";
import { getIconForContentType } from "../utils/getIconForContentType";

/* -------------------- Helpers -------------------- */
const SectionHeader = ({ children }) => (
  <div className={drstyles.sectionHeader}>{children}</div>
);

const Field = ({ label, children }) => (
  <div className="mb-1">
    <strong>{label}:</strong> {children ?? <span className="text-muted">N/A</span>}
  </div>
);

const renderCodeable = (cc) =>
  cc ? (
    <>
      {cc.text && <div>{cc.text}</div>}
      {cc.coding?.map((c, idx) => (
        <div key={idx} className="text-muted small ps-3">
          {c.system ? `${c.system} → ` : ""}
          {c.code} — {c.display}
        </div>
      ))}
    </>
  ) : (
    <span className="text-muted">N/A</span>
  );

const renderReference = (ref, label, onClick) => {
  if (!ref) return <span className="text-muted">N/A</span>;

  return (
    <button
      className="btn btn-link p-0"
      onClick={() => onClick?.(ref, label || ref)}
    >
      {label || ref}
    </button>
  );
};


const getExtensionFromContentType = (contentType) => {
  const map = {
    "application/pdf": "pdf",
    "image/jpeg": "jpg",
    "image/png": "png",
    "image/gif": "gif",
    "image/webp": "webp",
    "image/bmp": "bmp",
    "text/plain": "txt",
    "text/html": "html",
    "application/json": "json",
    "application/xml": "xml",
    "application/msword": "doc",
    "application/vnd.openxmlformats-officedocument.wordprocessingml.document": "docx",
  };
  return map[contentType] || "dat";
};

/* Normalize attachments */
const normalizeAttachmentsFromDocumentReference = (resource) => {
  const result = [];
  if (!resource) return result;

  if (Array.isArray(resource.content)) {
    resource.content.forEach((c, idx) => {
      const att = c.attachment;
      if (!att) return;
      result.push({
        title: att.title || att.label || `content ${idx + 1}`,
        url: att.url || null,
        data: att.data || null,
        contentType: att.contentType || null,
        creation: att.creation || null,
        source: "content",
        raw: att,
      });
    });
  }

  if (Array.isArray(resource.presentedForm)) {
    resource.presentedForm.forEach((att, idx) => {
      result.push({
        title: att.title || `presentedForm ${idx + 1}`,
        url: att.url || null,
        data: att.data || null,
        contentType: att.contentType || null,
        creation: att.creation || null,
        source: "presentedForm",
        raw: att,
      });
    });
  }

  return result;
};


/* -------------------- Main Component -------------------- */
const DocumentReferenceCardExtended = ({ resource, handleShowNested, fhirClient }) => {
  const [showModal, setShowModal] = useState(false);
  const [modalBlobUrl, setModalBlobUrl] = useState("");
  const [modalTitle, setModalTitle] = useState("");
  const [modalType, setModalType] = useState("generic");
  const [loadingAttachment, setLoadingAttachment] = useState(false);
  const attachments = normalizeAttachmentsFromDocumentReference(resource);
  const patients = useSelector((s) => s.patients || {});
  const providers = useSelector((s) => s.providers || {});
  const getState = () => ({ patients, providers });
  const [patientData, setPatientData] = useState(null);
  const [provider, setProvider] = useState(null);
  const [organization, setOrganization] = useState(null);
  const [encounterData, setEncounterData] = useState(null);
  const [loading, setLoading] = useState({ patient: false, provider: false, org: false });
  const dispatch = useDispatch();
  const store = useStore();


  console.log(resource);

  useEffect(() => {
    // Reset when resource changes
    setPatientData(null);
    setProvider(null);
    setOrganization(null);

    if (!resource) return;

    // Fetch patient (subject)
    const doFetchPatient = async () => {
      if (!resource?.subject?.reference || !fhirClient) return;
      try {
        setLoading((l) => ({ ...l, patient: true }));
        const p = await fetchPatientByReference(resource.subject.reference, fhirClient, store);
        setPatientData(p);
      } catch (err) {
        console.error("ObservationCardExtended: failed to fetch patient", err);
        setPatientData(null);
      } finally {
        setLoading((l) => ({ ...l, patient: false }));
      }
    };

    // Parse performer array: we'll look for Practitioner and Organization refs
    const doFetchAuthors = async () => {
      if (!Array.isArray(resource.author) || !fhirClient) return;

      // performer entries can be Reference objects or full resources
      // We'll prefer Practitioner and Organization if present
      let practitionerRef = null;
      let orgRef = null;

      for (const p of resource.author) {
        const ref = p?.reference || (p?.identifier ? null : null);
        if (!ref) {
          // if a full resource object is passed inline
          if (p?.resourceType === "Practitioner") {
            setProvider(p);
            continue;
          }
          if (p?.resourceType === "Organization") {
            setOrganization(p);
            continue;
          }
          continue;
        }

        if (ref.startsWith("Practitioner/") && !practitionerRef) practitionerRef = ref;
        if (ref.startsWith("Organization/") && !orgRef) orgRef = ref;
      }

      // Fetch Practitioner via providerService if we have a ref
      if (practitionerRef) {
        try {
          setLoading((l) => ({ ...l, provider: true }));
          const prov = await fetchProviderByReference(practitionerRef, fhirClient, store);
          if (prov) setProvider(prov);
        } catch (err) {
          console.error("ObservationCardExtended: failed to fetch provider", err);
        } finally {
          setLoading((l) => ({ ...l, provider: false }));
        }
      }

      // Fetch Organization directly
      if (orgRef) {
        try {
          setLoading((l) => ({ ...l, org: true }));
          const org = await fetchOrganizationByReference(orgRef, fhirClient, store);
          setOrganization(org);
        } catch (err) {
          console.error("ObservationCardExtended: failed to fetch organization", err);
          setOrganization(null);
        } finally {
          setLoading((l) => ({ ...l, org: false }));
        }
      }
    };

    doFetchPatient();
    doFetchAuthors();

    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [resource, fhirClient]);


  const patientNameObj = patientData?.name?.[0];
  const patientFullName = patientNameObj ? `${patientNameObj.given?.join(" ") || ""} ${patientNameObj.family || ""}`.trim() : "Unknown";
  const patientPhotoUrl = patientData?.photo?.[0]?.url || (patientData?.gender === "female" ? FemalePatient : MalePatient);
  const providerNameObj = provider?.name?.[0];
  const providerFullName = providerNameObj ? `${providerNameObj.prefix?.join(" ") || ""} ${providerNameObj.given?.join(" ") || ""} ${providerNameObj.family || ""}`.trim() : "Unknown Provider";
  const providerPhotoUrl = provider?.photo?.[0]?.url || (provider?.gender === "female" ? FemaleProvider : MaleProvider);
  const orgDisplayName = organization?.name || (organization?.id ? `Organization/${organization.id}` : "Unknown Organization");
  const orgIcon = DefaultOrg || DefaultOrg || ""; // replace DefaultProvider with your org icon path if available

  return (
    <div className="p-4 border rounded shadow-sm bg-white">

      {/* ===================== SUBJECT + PERFORMER (Patient, Provider, Org) ===================== */}
      <div className={drstyles.headerRow}>
        {/* Patient block */}
        <div className={drstyles.entityBlock}>
          <button
            className={drstyles.entityImageButton}
            onClick={() => handleShowNested?.(patientData, patientFullName)}
          >
            <img src={patientPhotoUrl} alt="Patient" className={drstyles.avatar} />
          </button>
          <div>
            <Field label="Patient">{patientFullName}</Field>
            <Field label="Birth Date">{patientData?.birthDate}</Field>
          </div>
        </div>

        {/* Provider + Organization block */}
        <div className={drstyles.organizationBlock}>
          <button
            className={drstyles.entityImageButton}
            onClick={() => handleShowNested?.(provider, providerFullName)}
          >
            <img src={providerPhotoUrl || DefaultProvider} alt="Provider" className={drstyles.avatar} />
          </button>

          <div className={drstyles.orgText} style={{ marginRight: "1rem" }}>
            <Field label="Performer">{providerFullName}</Field>
            <Field label="Active">{provider ? (provider.active ? "Yes" : "No") : "N/A"}</Field>
          </div>

          <button
            className={drstyles.entityImageButton}
            onClick={() => handleShowNested?.(organization, orgDisplayName)}
          >
            <img src={orgIcon} alt="Organization" className={drstyles.avatar} />
          </button>

          <div className={drstyles.orgText}>
            <div className={drstyles.orgName}>{orgDisplayName}</div>
            <div className={drstyles.orgType}>
              {organization?.type?.text || organization?.type?.coding?.[0]?.display || ""}
            </div>
          </div>
        </div>
      </div>

      {/* Identification */}
      <SectionHeader>Identification</SectionHeader>
     <div className={styles.indented}>
        <Field label="Document ID">{resource.id}</Field>
        <Field label="Status">{resource.status}</Field>
        <Field label="Doc Status">{resource.docStatus}</Field>
        <Field label="Type">{renderCodeable(resource.type)}</Field>
        {Array.isArray(resource.identifier) && resource.identifier.length > 0 && (
          <Field label="Identifiers">
            {resource.identifier.map((id, idx) => (
              <div key={idx} className="ps-3">{id.system} — {id.value}</div>
            ))}
          </Field>
        )}
      </div>

      {/* Context */}
      <SectionHeader>Context</SectionHeader>
      <div className={styles.indented}>
        <Field label="Encounter">{renderReference(resource.context?.encounter?.reference, "Encounter", handleShowNested)}</Field>
        <Field label="Event">{resource.context?.event?.map((e, i) => <div key={i}>{renderCodeable(e)}</div>)}</Field>
        <Field label="Period">{resource.context?.period ? `${resource.context.period.start || "?"} → ${resource.context.period.end || "?"}` : "N/A"}</Field>
        <Field label="Facility Type">{renderCodeable(resource.context?.facilityType)}</Field>
      </div>

      {/* Content (attachments) */}
      <SectionHeader>Content</SectionHeader>
      <div>
        {attachments.length > 0 ? attachments.map((att, idx) => {
          const attachmentRef = {
            url: att.url || null,
            data: att.data || null,
            contentType: att.contentType || null,
            title: att.title || "Attachment"
          };

          const label = attachmentRef.title;

          return (
            <div key={idx} className="border rounded p-2 mb-2 d-flex align-items-start">
              {/* Icon */}
              <div className="me-2">
                {getIconForContentType(att.contentType, "CommPayload")}
              </div>

              {/* Main content */}
              <div className="flex-grow-1">
                {/* File name on left, buttons on right */}
                <div className="d-flex align-items-center justify-content-between">
                  {/* File label */}
                  <div className="fw-bold text-truncate me-3" style={{ maxWidth: "70%" }}>
                    {label}{" "}
                    <span className="text-muted">({attachmentRef.contentType || "N/A"})</span>
                  </div>

                  {/* Buttons aligned right */}
                  <div className="d-flex">
                    {/* OPEN BUTTON */}
                    <button
                      className="btn btn-sm btn-outline-primary me-2"
                      onClick={async () => {
                        try {
                          const fetched = await fetchAttachment(attachmentRef, fhirClient);
                          if (fetched?.blob) {
                            const url = URL.createObjectURL(fetched.blob);
                            window.open(url, "_blank");
                          } else {
                            alert("Failed to open attachment.");
                          }
                        } catch (err) {
                          console.error("Failed to open attachment", err);
                          alert("Failed to open attachment.");
                        }
                      }}
                    >
                      Open
                    </button>

                    {/* DOWNLOAD BUTTON */}
                    <button
                      className="btn btn-sm btn-outline-primary"
                      onClick={async () => {
                        try {
                          const fetched = await fetchAttachment(attachmentRef, fhirClient);
                          if (fetched?.blob) {
                            const blobUrl = URL.createObjectURL(fetched.blob);
                            const a = document.createElement("a");
                            a.href = blobUrl;
                            a.download = (attachmentRef.title || "file").replace(/\s+/g, "_");
                            a.click();
                            URL.revokeObjectURL(blobUrl);
                          } else {
                            alert("Failed to download attachment.");
                          }
                        } catch (err) {
                          console.error("Failed to download attachment", err);
                          alert("Failed to download attachment.");
                        }
                      }}
                    >
                      Download
                    </button>
                  </div>
                </div>

                {/* Optional metadata below */}
                {att.source && <div className="text-muted small">{att.source}</div>}
                {att.creation && <div className="text-muted small">Created: {att.creation}</div>}
              </div>
            </div>
          );


        }) : (
          <div className="text-muted">No content attachments found</div>
        )}
      </div>

      {/* Relations */}
      {Array.isArray(resource.relatesTo) && resource.relatesTo.length > 0 && (
        <>
          <SectionHeader>Relations</SectionHeader>
          <div className={styles.indented}>
            {resource.relatesTo.map((r, i) => (
              <div key={i} className="mb-2">
                <strong>{r.code}:</strong> {renderReference(r.target?.reference, r.target?.display || r.target?.reference, handleShowNested)}
              </div>
            ))}
          </div>
        </>
      )}

      {/* Notes */}
      {Array.isArray(resource.note) && resource.note.length > 0 && (
        <>
          <SectionHeader>Notes</SectionHeader>
          <div className={styles.indented}>
            {resource.note.map((n, i) => (
              <div key={i} className="mb-2">
                {n.text} <span className="text-muted small">({n.authorString || n.authorReference?.reference})</span>
              </div>
            ))}
          </div>
        </>
      )}

      {/* Metadata */}
      <SectionHeader>Metadata</SectionHeader>
    <div className={styles.indented}>
        <Field label="Language">{resource.language}</Field>
        <Field label="Created">{resource.created}</Field>
        <Field label="Indexed">{resource.indexed}</Field>
      </div>

      {/* Attachment modal */}
      <Modal
        show={showModal}
        onHide={() => {
          setShowModal(false);
          if (modalBlobUrl) {
            URL.revokeObjectURL(modalBlobUrl);
            setModalBlobUrl("");
          }
        }}
        size="xl"
        fullscreen="md-down"
        centered
      >
        <Modal.Header closeButton>
          <Modal.Title>{modalTitle}</Modal.Title>
        </Modal.Header>
        <Modal.Body style={{ height: "80vh" }}>
          {modalType === "pdf" && <PDFViewer blobUrl={modalBlobUrl} />}
          {modalType === "image" && <img src={modalBlobUrl} alt={modalTitle} style={{ maxWidth: "100%", maxHeight: "100%" }} />}
          {(modalType === "text" || modalType === "json" || modalType === "html") && (
            <iframe src={modalBlobUrl} title={modalTitle} style={{ width: "100%", height: "100%", border: "none" }} />
          )}
          {modalType === "generic" && <p className="text-muted text-center">Preview not supported for this file type.</p>}
        </Modal.Body>
      </Modal>
    </div>
  );


};

export default DocumentReferenceCardExtended;
