// ObservationCardExtended.jsx
import React, { useEffect, useState } from "react";
import { useSelector, useDispatch, useStore } from "react-redux";
import { fetchPatientByReference } from "../services/patientService";
import { fetchProviderByReference } from "../services/providerService";
import { fetchEncounterByReference } from "../services/encounterService";
import { fetchOrganizationByReference } from "../services/organizationService";
import FemalePatient from "../assets/scanner-female.png";
import MalePatient from "../assets/scanner-male.png";
import FemaleProvider from "../assets/Doctor_Female.jpg";
import MaleProvider from "../assets/Doctor_Male_96.png";
import DefaultProvider from "../assets/Doctor_Male_96.png";
import DefaultOrg from "../assets/world-health.png";
import obsstyles from "./ObservationCardExtended.module.css";
import styles from "./GenericFHIRViewerModal.module.css";
import { resolveName } from "../utils/messageUtils";
import { formatLocalDate } from "../utils/dateUtils";
import { renderReference } from "../utils/renderUtils";

const SectionHeader = ({ children }) => (
  <div className={obsstyles.sectionHeader}>{children}</div>
);

const Field = ({ label, children }) => (
  <div className="mb-1">
    <strong>{label}:</strong> {children || <span className="text-muted">N/A</span>}
  </div>
);

const renderCodeable = (cc) => {
  if (!cc) return <span className="text-muted">N/A</span>;

  // If coding array exists, list each coding
  if (cc.coding?.length) {
    return (
      <>
        {cc.coding.map((c, idx) => (
          <div key={idx} className="text-muted small ps-3">
            {c.system ? `${c.system} → ` : ""}
            {c.code} — {c.display || c.code}
          </div>
        ))}
      </>
    );
  }

  // Fallback to text
  if (cc.text) return <div>{cc.text}</div>;

  return <span className="text-muted">N/A</span>;
};


const renderQuantity = (q) =>
  q ? (
    <>
      {q.value} {q.unit && <span>({q.unit})</span>}
      <div className="text-muted small">{q.system}</div>
    </>
  ) : (
    <span className="text-muted">N/A</span>
  );

const renderValueX = (obs) => {
  if (!obs) return <span className="text-muted">No value reported</span>;

  const value = obs.valueQuantity || obs.valueCodeableConcept || obs.valueString || obs.valueBoolean !== undefined ||
    obs.valueInteger !== undefined || obs.valueRange || obs.valueRatio || obs.valueDateTime ||
    obs.valueTime || obs.valuePeriod || obs.valueSampledData;

  if (!value && obs.dataAbsentReason) {
    return <span className="text-muted">No value reported ({obs.dataAbsentReason.text || obs.dataAbsentReason.code})</span>;
  }

  if (obs.valueQuantity) return renderQuantity(obs.valueQuantity);
  if (obs.valueCodeableConcept) return renderCodeable(obs.valueCodeableConcept);
  if (obs.valueString) return <span>{obs.valueString}</span>;
  if (obs.valueBoolean !== undefined) return <span>{obs.valueBoolean ? "True" : "False"}</span>;
  if (obs.valueInteger !== undefined) return <span>{obs.valueInteger}</span>;
  if (obs.valueRange)
    return (
      <>
        Low: {renderQuantity(obs.valueRange.low)} <br />
        High: {renderQuantity(obs.valueRange.high)}
      </>
    );
  if (obs.valueRatio)
    return (
      <>
        Numerator: {renderQuantity(obs.valueRatio.numerator)} <br />
        Denominator: {renderQuantity(obs.valueRatio.denominator)}
      </>
    );
  if (obs.valueDateTime) return <span>{obs.valueDateTime}</span>;
  if (obs.valueTime) return <span>{obs.valueTime}</span>;
  if (obs.valuePeriod)
    return (
      <>
        From: {obs.valuePeriod.start || "?"} <br />
        To: {obs.valuePeriod.end || "?"}
      </>
    );
  if (obs.valueSampledData)
    return <span className="text-muted small">SampledData (graph not implemented)</span>;

  return <span className="text-muted">No value reported</span>;
};




/* -------------------- MAIN COMPONENT -------------------- */
const ObservationCardExtended = ({ resource, handleShowNested, fhirClient }) => {
  const store = useStore();
  const [patientData, setPatientData] = useState(null);
  const [provider, setProvider] = useState(null);
  const [organization, setOrganization] = useState(null);
  const [encounterData, setEncounterData] = useState(null);
  const [loading, setLoading] = useState({ patient: false, provider: false, org: false });

  useEffect(() => {
    // Reset when resource changes
    setPatientData(null);
    setProvider(null);
    setOrganization(null);

    if (!resource) return;

    // Fetch patient (subject)
    const doFetchPatient = async () => {
      if (!resource?.subject?.reference || !fhirClient) return;
      try {
        setLoading((l) => ({ ...l, patient: true }));
        const p = await fetchPatientByReference(resource.subject.reference, fhirClient, store);
        setPatientData(p);
      } catch (err) {
        console.error("ObservationCardExtended: failed to fetch patient", err);
        setPatientData(null);
      } finally {
        setLoading((l) => ({ ...l, patient: false }));
      }
    };

    // Parse performer array: we'll look for Practitioner and Organization refs
    const doFetchPerformers = async () => {
      if (!Array.isArray(resource.performer) || !fhirClient) return;

      // performer entries can be Reference objects or full resources
      // We'll prefer Practitioner and Organization if present
      let practitionerRef = null;
      let orgRef = null;

      for (const p of resource.performer) {
        const ref = p?.reference || (p?.identifier ? null : null);
        if (!ref) {
          // if a full resource object is passed inline
          if (p?.resourceType === "Practitioner") {
            setProvider(p);
            continue;
          }
          if (p?.resourceType === "Organization") {
            setOrganization(p);
            continue;
          }
          continue;
        }

        if (ref.startsWith("Practitioner/") && !practitionerRef) practitionerRef = ref;
        if (ref.startsWith("Organization/") && !orgRef) orgRef = ref;
      }

      // Fetch Practitioner via providerService if we have a ref
      if (practitionerRef) {
        try {
          setLoading((l) => ({ ...l, provider: true }));
          const prov = await fetchProviderByReference(practitionerRef, fhirClient, store);
          if (prov) setProvider(prov);
        } catch (err) {
          console.error("ObservationCardExtended: failed to fetch provider", err);
        } finally {
          setLoading((l) => ({ ...l, provider: false }));
        }
      }

      // Fetch Organization directly
      if (orgRef) {
        try {
          setLoading((l) => ({ ...l, org: true }));
          const org = await fetchOrganizationByReference(orgRef, fhirClient, store);
          setOrganization(org);
        } catch (err) {
          console.error("ObservationCardExtended: failed to fetch organization", err);
          setOrganization(null);
        } finally {
          setLoading((l) => ({ ...l, org: false }));
        }
      }
    };

    doFetchPatient();
    doFetchPerformers();

    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [resource, fhirClient]);


  useEffect(() => {
    const fetchEncounter = async () => {
      if (resource?.encounter?.reference && fhirClient) {
        const enc = await fetchEncounterByReference(resource.encounter.reference, fhirClient, store);
        setEncounterData(enc);
      }
    };
    fetchEncounter();
  }, [resource, fhirClient]);


  // Derived display names + images
  const patientNameObj = patientData?.name?.[0];
  const patientFullName = patientNameObj ? `${patientNameObj.given?.join(" ") || ""} ${patientNameObj.family || ""}`.trim() : "Unknown";
  const patientPhotoUrl = patientData?.photo?.[0]?.url || (patientData?.gender === "female" ? FemalePatient : MalePatient);
  const providerNameObj = provider?.name?.[0];
  const providerFullName = providerNameObj ? `${providerNameObj.prefix?.join(" ") || ""} ${providerNameObj.given?.join(" ") || ""} ${providerNameObj.family || ""}`.trim() : "Unknown Provider";
  const providerPhotoUrl = provider?.photo?.[0]?.url || (provider?.gender === "female" ? FemaleProvider : MaleProvider);
  const orgDisplayName = organization?.name || (organization?.id ? `Organization/${organization.id}` : "Unknown Organization");
  const orgIcon = DefaultOrg || DefaultOrg || ""; // replace DefaultProvider with your org icon path if available
  const identifierList = resource.identifier || [];
  const categories = resource.category || [];
  const components = resource.component || [];
  const interpretation = resource.interpretation || [];
  const referenceRange = resource.referenceRange || [];

  return (
    <div className={`p-4 border rounded shadow-sm bg-white`}>
      {/* ===================== SUBJECT + PERFORMER (Patient, Provider, Org) ===================== */}
      <div className={obsstyles.headerRow}>
        {/* Patient block */}
        <div className={obsstyles.entityBlock}>
          <button
            className={obsstyles.entityImageButton}
            onClick={() => handleShowNested?.(patientData, patientFullName)}
          >
            <img src={patientPhotoUrl} alt="Patient" className={obsstyles.avatar} />
          </button>
          <div>
            <Field label="Patient">{patientFullName}</Field>
            <Field label="Birth Date">{patientData?.birthDate}</Field>
          </div>
        </div>

        {/* Provider + Organization block */}
        <div className={obsstyles.organizationBlock}>
          <button
            className={obsstyles.entityImageButton}
            onClick={() => handleShowNested?.(provider, providerFullName)}
          >
            <img src={providerPhotoUrl || DefaultProvider} alt="Provider" className={obsstyles.avatar} />
          </button>

          <div className={obsstyles.orgText} style={{ marginRight: "1rem" }}>
            <Field label="Performer">{providerFullName}</Field>
            <Field label="Active">{provider ? (provider.active ? "Yes" : "No") : "N/A"}</Field>
          </div>

          <button
            className={obsstyles.entityImageButton}
            onClick={() => handleShowNested?.(organization, orgDisplayName)}
          >
            <img src={orgIcon} alt="Organization" className={obsstyles.avatar} />
          </button>

          <div className={obsstyles.orgText}>
            <div className={obsstyles.orgName}>{orgDisplayName}</div>
            <div className={obsstyles.orgType}>
              {organization?.type?.text || organization?.type?.coding?.[0]?.display || ""}
            </div>
          </div>
        </div>
      </div>

      {/* ===================== IDENTIFICATION ===================== */}
      <SectionHeader>Identification</SectionHeader>
      <div className="ps-5 pt-2">
        <Field label="Observation ID">{resource.id}</Field>
        <Field label="Status">{resource.status}</Field>
        <Field label="Code">{renderCodeable(resource.code)}</Field>
        {identifierList.length > 0 && (
          <Field label="Identifiers">
            {identifierList.map((id, idx) => (
              <div key={idx} className="ps-3">{id.system} — {id.value}</div>
            ))}
          </Field>
        )}
        {categories.length > 0 && (
          <Field label="Categories">
            {categories.map((cat, idx) => (
              <div key={idx} className="mb-2">{renderCodeable(cat)}</div>
            ))}
          </Field>
        )}
      </div>

      {/* ===================== TIMING ===================== */}
      <SectionHeader>Timing</SectionHeader>
       <div className={styles.indented}>
        <Field label="Effective">
          {resource.effectiveDateTime
            ? formatLocalDate(resource.effectiveDateTime)
            : resource.effectiveInstant
              ? formatLocalDate(resource.effectiveInstant)
              : resource.effectivePeriod
                ? `${formatLocalDate(resource.effectivePeriod.start) || "?"} → ${formatLocalDate(resource.effectivePeriod.end) || "?"}`
                : resource.effectiveTiming
                  ? "(Timing)"
                  : "N/A"}
        </Field>

        <Field label="Issued">
          {resource.issued ? formatLocalDate(resource.issued) : "N/A"}
        </Field>


        <Field label="Encounter">
          {encounterData ? (
            <button
              className="btn btn-link p-0"
              onClick={() => handleShowNested?.(encounterData, resolveName(encounterData, store))}
            >
              {resolveName(encounterData, store)}
            </button>
          ) : (
            <span className="text-muted">N/A</span>
          )}
        </Field>
      </div>

      {/* ===================== VALUE ===================== */}
      <SectionHeader>Observation Value</SectionHeader>
       <div className={styles.indented}>
        {resource.dataAbsentReason && !resource.valueQuantity && (
          <Field label="Data Absent Reason">{renderCodeable(resource.dataAbsentReason)}</Field>
        )}
        <Field label="Value">{renderValueX(resource)}</Field>
      </div>

      {/* ===================== INTERPRETATION ===================== */}
      {interpretation.length > 0 && (
        <>
          <SectionHeader>Interpretation</SectionHeader>
          <div className={styles.indented}>
            {interpretation.map((i, idx) => (
              <div key={idx} className="mb-2">{renderCodeable(i)}</div>
            ))}
          </div>
        </>
      )}

      {/* ===================== PROCEDURE CONTEXT ===================== */}
      <SectionHeader>Procedure Context</SectionHeader>
      <div className={styles.indented}>
        <Field label="Body Site">{renderCodeable(resource.bodySite)}</Field>
        <Field label="Method">{renderCodeable(resource.method)}</Field>
        <Field label="Specimen">{renderReference(resource.specimen?.reference, "Specimen", handleShowNested)}</Field>
        <Field label="Device">{renderReference(resource.device?.reference, "Device", handleShowNested)}</Field>
      </div>

      {/* ===================== REFERENCE RANGE ===================== */}
      {referenceRange.length > 0 && (
        <>
          <SectionHeader>Reference Ranges</SectionHeader>
          <div className={styles.indented}>
            {referenceRange.map((rr, idx) => (
              <div key={idx} className="border rounded p-2 mb-2 bg-light">
                <Field label="Low">{renderQuantity(rr.low)}</Field>
                <Field label="High">{renderQuantity(rr.high)}</Field>
                <Field label="Type">{renderCodeable(rr.type)}</Field>
                {rr.appliesTo?.length > 0 && (
                  <Field label="Applies To">
                    {rr.appliesTo.map((ap, i2) => (
                      <div key={i2} className="ps-3">{renderCodeable(ap)}</div>
                    ))}
                  </Field>
                )}
                {rr.age && (
                  <Field label="Age Range">{rr.age.low?.value} → {rr.age.high?.value}</Field>
                )}
                <Field label="Text">{rr.text}</Field>
              </div>
            ))}
          </div>
        </>
      )}

      {/* ===================== COMPONENTS ===================== */}
      {components.length > 0 && (
        <>
          <SectionHeader>Components</SectionHeader>
          <div className={styles.indented}>
            {components.map((comp, idx) => (
              <div key={idx} className="border rounded p-2 mb-3 bg-light">
                <Field label="Code">{renderCodeable(comp.code)}</Field>
                <Field label="Value">{renderValueX(comp)}</Field>
                {comp.dataAbsentReason && (
                  <Field label="Data Absent Reason">{renderCodeable(comp.dataAbsentReason)}</Field>
                )}
                {comp.interpretation?.length > 0 && (
                  <Field label="Interpretation">
                    {comp.interpretation.map((i2, j) => (
                      <div key={j} className="ps-3">{renderCodeable(i2)}</div>
                    ))}
                  </Field>
                )}
                {comp.referenceRange?.length > 0 && (
                  <Field label="Reference Ranges">
                    {comp.referenceRange.map((rr, k) => (
                      <div key={k} className="ps-3 mb-2">
                        Low: {renderQuantity(rr.low)} <br />
                        High: {renderQuantity(rr.high)}
                      </div>
                    ))}
                  </Field>
                )}
              </div>
            ))}
          </div>
        </>
      )}

      {/* ===================== NOTES ===================== */}
      {resource.note?.length > 0 && (
        <>
          <SectionHeader>Notes</SectionHeader>
         <div className={styles.indented}>
            {resource.note.map((n, idx) => (
              <div key={idx} className="mb-2">
                {n.text} <span className="text-muted small">({n.authorString || n.authorReference?.reference})</span>
              </div>
            ))}
          </div>
        </>
      )}

      {/* ===================== RELATIONSHIPS ===================== */}
      <SectionHeader>Relationships</SectionHeader>
     <div className={styles.indented}>
        <Field label="Based On">
          {resource.basedOn?.map((r, idx) =>
            r.reference ? (
              <button
                key={idx}
                className="btn btn-link p-0"
                onClick={() => handleShowNested?.(r.reference, resolveName(r.reference, store))}
              >
                {resolveName(r.reference, store)}
              </button>
            ) : (
              <span key={idx} className="text-muted">N/A</span>
            )
          )}
        </Field>

        <Field label="Part Of">
          {resource.partOf?.map((r, idx) =>
            r.reference ? (
              <button
                key={idx}
                className="btn btn-link p-0"
                onClick={() => handleShowNested?.(r.reference, resolveName(r.reference, store))}
              >
                {resolveName(r.reference, store)}
              </button>
            ) : (
              <span key={idx} className="text-muted">N/A</span>
            )
          )}
        </Field>

        <Field label="Has Member">
          {resource.hasMember?.map((r, idx) =>
            r.reference ? (
              <button
                key={idx}
                className="btn btn-link p-0"
                onClick={() => handleShowNested?.(r.reference, resolveName(r.reference, store))}
              >
                {resolveName(r.reference, store)}
              </button>
            ) : (
              <span key={idx} className="text-muted">N/A</span>
            )
          )}
        </Field>

        <Field label="Derived From">
          {resource.derivedFrom?.map((r, idx) =>
            r.reference ? (
              <button
                key={idx}
                className="btn btn-link p-0"
                onClick={() => handleShowNested?.(r.reference, resolveName(r.reference, store))}
              >
                {resolveName(r.reference, store)}
              </button>
            ) : (
              <span key={idx} className="text-muted">N/A</span>
            )
          )}
        </Field>


      </div>


      {/* ===================== METADATA ===================== */}
      <SectionHeader>Metadata</SectionHeader>
      <div className={styles.indented}>
        <Field label="Language">{resource.language}</Field>
        <Field label="Last Updated">
          {resource.meta?.lastUpdated
            ? formatLocalDate(resource.meta.lastUpdated)
            : "N/A"}
        </Field>

        <Field label="Version">{resource.meta?.versionId}</Field>
      </div>
    </div>
  );

};

export default ObservationCardExtended;
