// fetchAttachment.js
import { fetchBinaryBlob } from "./fetchBinaryBlob"; // adjust path as needed

/**
 * Fetch a FHIR attachment/resource safely.
 *
 * Supports:
 *  - Local base64 files (no URL)
 *  - External URLs (http/https)
 *  - FHIR resources (Binary, DocumentReference, DiagnosticReport, Observation)
 * 
 * 
 * Attachment Type	Behaviour
      FHIR Binary	fetch → blob → open
      DocumentReference	fetch → inspect attachment → open
      Media.link	fetch referenced Media → open
      Local base64	decode → blob → open
      External ARC/PACS/HTTPS URL	open directly in new tab


 *
 * @param {Object} attachmentRef - { url?, data?, contentType?, title? }
 * @param {Object} fhirClient - Initialized FHIR client with request()
 */
export const fetchAttachment = async (attachmentRef, fhirClient) => {
  console.log("----------------------fetchAttachment: starting fetch", attachmentRef);

  // ---------------------------------------------------------------------
  // 1️⃣ Local Base64 file
  // ---------------------------------------------------------------------
  if (!attachmentRef?.url && attachmentRef?.data) {
    console.log("fetchAttachment: Detected local base64 file, decoding directly");
    try {
      const byteCharacters = atob(attachmentRef.data);
      const byteNumbers = Array.from(byteCharacters, c => c.charCodeAt(0));
      const blob = new Blob([new Uint8Array(byteNumbers)], {
        type: attachmentRef.contentType || "application/octet-stream"
      });

      return {
        type: "LocalFile",
        title: attachmentRef.title || "file",
        contentType: attachmentRef.contentType,
        blob
      };
    } catch (err) {
      console.error("fetchAttachment: failed to decode base64 local file", err);
      return { error: "Failed to decode local base64 attachment" };
    }
  }

  // ---------------------------------------------------------------------
  // 2️⃣ External HTTP/HTTPS URL
  // ---------------------------------------------------------------------
  if (attachmentRef.url?.startsWith("http")) {
    console.log("fetchAttachment: Detected external URL", attachmentRef.url);
    return {
      type: "ExternalURL",
      title: attachmentRef.title || attachmentRef.url,
      contentType: attachmentRef.contentType,
      url: attachmentRef.url
    };
  }

  // ---------------------------------------------------------------------
  // 3️⃣ FHIR URL-based fetch (Binary, DocumentReference, etc)
  // ---------------------------------------------------------------------
  if (!attachmentRef?.url) {
    console.warn("fetchAttachment: no URL in attachmentRef", attachmentRef);
    return { error: "No URL provided" };
  }

  const url = attachmentRef.url;
  console.log("fetchAttachment: fetching FHIR URL", url);

  try {
    const response = await fhirClient.request(url, { headers: { Accept: attachmentRef.contentType || "*/*" } });

    // Raw fetch Response
    if (response instanceof Response) {
      const blob = await response.blob();
      return {
        type: "Binary",
        title: attachmentRef.title || url,
        contentType: blob.type || attachmentRef.contentType,
        blob
      };
    }

    // FHIR resource
    const resource = response;
    console.log("fetchAttachment: fetched resource type", resource?.resourceType, "id", resource?.id);

    switch (resource.resourceType) {
      case "Binary": {
        if (resource.data) {
          const byteCharacters = atob(resource.data);
          const byteNumbers = Array.from(byteCharacters, c => c.charCodeAt(0));
          const blob = new Blob([new Uint8Array(byteNumbers)], { type: resource.contentType });
          return {
            type: "Binary",
            id: resource.id,
            title: attachmentRef.title || resource.id,
            contentType: resource.contentType,
            blob
          };
        }
        return { type: "Binary", id: resource.id, title: attachmentRef.title || resource.id, url: attachmentRef.url };
      }

      case "DocumentReference": {
        const attachment = resource.content?.[0]?.attachment || resource.attachment || null;
        const title = attachment?.title || resource.description || `DocumentReference/${resource.id}`;
        return {
          type: "DocumentReference",
          id: `DocumentReference/${resource.id}`,
          resource,
          title,
          attachment,
          contentType: attachment?.contentType,
          url: attachment?.url || null,
          data: attachment?.data || null
        };
      }

      case "Observation":
      case "DiagnosticReport":
        return {
          type: resource.resourceType,
          id: `${resource.resourceType}/${resource.id}`,
          resource,
          title: resource.code?.text || `${resource.resourceType}/${resource.id}`
        };

      default:
        return { type: resource.resourceType || "Unknown", id: resource.id, resource };
    }
  } catch (err) {
    console.error("fetchAttachment: fetch failed for URL", url, err);
    return { error: `Fetch failed: ${err.message}` };
  }
};
