// renderUtils.js
import React from "react";
import ObservationIcon from "../assets/microscope_96.png";
import DiagnosticReportIcon from "../assets/diagnostic-report-1.png";
import DocumentIcon from "../assets/doc-ref-1.png";
import MediaIcon from "../assets/media-1.png";
import { getIconForContentType } from "./getIconForContentType";
import styles from "./renderUtils.module.css";
import { Badge } from "react-bootstrap";
import { FiArrowUpRight, FiArrowDownRight, FiClock, FiSearch } from "react-icons/fi";
import { FaPen, FaEye, FaStar, FaRegClock, FaRegCommentDots } from "react-icons/fa";

import PatientCard from "../cards/PatientCardExtended";
import ProviderCard from "../cards/ProviderCard";
import EncounterCard from "../cards/EncounterCard";
import ObservationCard from "../cards/ObservationCard";
import DiagnosticCard from "../cards/DiagnosticCard";
import DocumentReferenceCard from "../cards/DocumentReferenceCard";
import CommunicationCard from "../cards/CommunicationCardExtended";


const variants = {
    stat: "warning",
    routine: "info",
    urgent: "danger",
    asap: "warning"
};

/**
 * Maps a priority string to a Bootstrap variant.
 * @param {string} priority
 * @returns {string}
 */
function getPriorityVariant(priority) {
    return variants[priority?.toLowerCase()] || "secondary";
}


export const renderCommunicationAttachments = (comm = {}) => {
    //console.log("Rendering communicatin attachments......");
    const seen = {
        file: false,
        observation: false,
        document: false,
        diagnostic: false
    };

    const icons = [];

    const addIcon = (type, element) => {
        if (!seen[type]) {
            seen[type] = true;
            icons.push(
                <span key={type} style={{ marginLeft: "0.4rem" }}>
                    {element}
                </span>
            );
        }
    };

    // -----------------------------
    // Handle payload[]
    // -----------------------------
    (comm.payload || []).forEach((p) => {
        // 1) contentAttachment → FILES using helper
        if (p.contentAttachment) {
            const ct = p.contentAttachment.contentType || "";
            const title = p.contentAttachment.title || "";

            // Pass a combined string to help filename detection inside helper
            const detectString = `${ct} ${title}`.trim().toLowerCase();

            const icon = getIconForContentType(detectString, "contentAttachment");

            addIcon("file", icon);     // one generic file group (PDF, Word, etc.)
        }

        // 2) contentReference → resource icons
        if (p.contentReference?.reference) {
            const ref = p.contentReference.reference;

            if (ref.startsWith("Observation/")) {
                addIcon(
                    "observation",
                    <img
                        src={ObservationIcon}
                        alt="Observation Attachment"
                        style={{ width: 20, height: 20 }}
                    />
                );
            }

            if (ref.startsWith("DocumentReference/")) {
                addIcon(
                    "document",
                    <img
                        src={DocumentIcon}
                        alt="Document Attachment"
                        style={{ width: 20, height: 20 }}
                    />
                );
            }

            if (ref.startsWith("DiagnosticReport/")) {
                addIcon(
                    "diagnostic",
                    <img
                        src={DiagnosticReportIcon}
                        alt="Diagnostic Report Attachment"
                        style={{ width: 20, height: 20 }}
                    />
                );
            }
        }
    });

    // -----------------------------
    // Handle about[]
    // -----------------------------
    (comm.about || []).forEach((refObj) => {
        const ref = refObj.reference || "";

        if (ref.startsWith("Observation/")) {
            addIcon(
                "observation",
                <img
                    src={ObservationIcon}
                    alt="Observation Attachment"
                    style={{ width: 20, height: 20 }}
                />
            );
        }

        if (ref.startsWith("DocumentReference/")) {
            addIcon(
                "document",
                <img
                    src={DocumentIcon}
                    alt="Document Attachment"
                    style={{ width: 20, height: 20 }}
                />
            );
        }

        if (ref.startsWith("DiagnosticReport/")) {
            addIcon(
                "diagnostic",
                <img
                    src={DiagnosticReportIcon}
                    alt="Diagnostic Report Attachment"
                    style={{ width: 20, height: 20 }}
                />
            );
        }
    });

    return icons.length > 0 ? <>{icons}</> : null;
};
export const getResourceIcon = (resourceType) => {
    if (!resourceType) return null;

    const type = resourceType.toLowerCase();

    if (type === "observation") {
        return <img src={ObservationIcon} alt="Observation" className={styles.resourceIcon} />;
    }

    if (type === "documentreference") {
        return <img src={DocumentIcon} alt="Document Reference" className={styles.resourceIcon} />;
    }

    if (type === "diagnosticreport") {
        return <img src={DiagnosticReportIcon} alt="Diagnostic Report" className={styles.resourceIcon} />;
    }

    if (type === "media") {
        return <img src={MediaIcon} alt="Media" className={styles.resourceIcon} />;
    }


    return null;
};

export function renderPriorityBadge(priority) {
    const variant = getPriorityVariant(priority);

    return (
        <Badge bg={variant} className="mx-0" style={{ fontSize: "0.75rem" }}>
            {priority?.toUpperCase() || "N/A"}
        </Badge>
    );
}


export function renderReference(ref, label, onClick) {
    //console.log("renderReference called with:", { ref, label });

    if (!ref) return <span className="text-muted">N/A</span>;
    return (
        <button
            className="btn btn-link p-0"
            onClick={() => onClick?.(ref, label || ref)}
        >
            {label || ref}
        </button>
    );
};


export function renderPriority(priority) {
    if (!priority) return <Badge bg="secondary">Unknown</Badge>;

    const colorMap = {
        stat: "danger",
        asap: "warning",
        urgent: "info",
        routine: "success"
    };

    const level = priority.toLowerCase();
    const color = colorMap[level] || "secondary";

    return <Badge bg={color}>{priority.toUpperCase()}</Badge>;
}


// renderCard.js
export function renderCard(resource, extraProps = {}) {
    if (!resource || typeof resource !== "object") return null;

    const commonProps = {
        depth: 0,
        ...extraProps
    };

    switch (resource.resourceType) {

        case "Patient":
            return (
                <PatientCard
                    patientData={resource}
                    {...commonProps}
                />
            );

        case "Practitioner":
            return (
                <ProviderCard
                    practitionerData={resource}
                    {...commonProps}
                />
            );

        case "Encounter":
            return (
                <EncounterCard
                    encounterData={resource}
                    {...commonProps}
                />
            );

        case "Observation":
            return (
                <ObservationCard
                    observationData={resource}
                    title={
                        resource.code?.text ||
                        resource.code?.coding?.[0]?.display ||
                        "Observation"
                    }
                    {...commonProps}
                />
            );

        case "DiagnosticReport":
            return (
                <DiagnosticCard
                    reportData={resource}
                    title={
                        resource.code?.text ||
                        resource.code?.coding?.[0]?.display ||
                        "Diagnostic Report"
                    }
                    {...commonProps}
                />
            );

        case "DocumentReference":
            return (
                <DocumentReferenceCard
                    documentData={resource}
                    title={
                        resource.description ||
                        resource.content?.[0]?.attachment?.title ||
                        "Document Reference"
                    }
                    {...commonProps}
                />
            );

        case "Communication":
            return (
                <CommunicationCard
                    resource={resource}
                    {...commonProps}
                />
            );

        default:
            return (
                <div style={{ padding: "1rem", color: "#666" }}>
                    Unsupported resource type: <strong>{resource.resourceType}</strong>
                </div>
            );
    }
}

export const getDirectionIcon = (key) => {
    switch (key) {
        case "incoming": return <FiArrowDownRight style={{ color: "#dc3545", marginRight: "0.4rem" }} />;
        case "outgoing": return <FiArrowUpRight style={{ color: "#0d6efd", marginRight: "0.4rem" }} />;
        case "starred": return <FaStar style={{ color: "#ffc107", marginRight: "0.4rem" }} />;
        case "snoozed": return <FaRegClock style={{ color: "#6c757d", marginRight: "0.4rem" }} />;
        default: return null;
    }
};






