import { registerProvider } from "../slices/providerRegistrySlice";

/**
 * Fetches a provider by ID:
 * - Checks the Redux store first
 * - If not present, fetches from FHIR server and registers it
 */
export const fetchProvider = async (providerId, fhirClient, store, { forceFetch = false } = {}) => {
    console.log("Fetching provider..............");
    if (!providerId || !fhirClient) return null;

    // 1. Check Redux store cache
    const cached = store.getState().providers?.[providerId];
    if (cached && !forceFetch) return cached;

    try {
        console.log(`🔎 Fetching Practitioner/${providerId}`);

        // 2. Fetch from FHIR server
        const fetched = await fhirClient.request(`Practitioner/${providerId}`);

        // -----------------------------
        // 3. Only dispatch on safe success
        // -----------------------------
        if (!fetched || fetched.resourceType !== "Practitioner") {
            console.warn(`⚠️ Not a valid Practitioner resource for ID ${providerId}, skipping dispatch.`);
            return null;
        }

        store.dispatch(registerProvider(fetched));
        return fetched;

    } catch (err) {

        // -----------------------------
        // 4. Safe and correct error handling
        // -----------------------------
        const status = err?.response?.status;

        if (status === 404) {
            console.warn(`❌ Practitioner/${providerId} not found (404). Not dispatching.`);
            return null;
        }

        if (status === 410) {
            console.warn(`⚠️ Practitioner/${providerId} has been deleted (410 Gone).`);
            return null;
        }

        console.error(`❌ Error fetching Practitioner/${providerId}:`, err);
        return null;
    }
};


export const fetchProviderByReference = async (ref, fhirClient, store, options = {}) => {
    if (!ref || !ref.startsWith("Practitioner/") || ref === "Practitioner/undefined") {
        console.warn("⚠️ Invalid provider reference:", ref);
        return null;
    }

    const providerId = ref.split("/")[1];
    if (!providerId) {
        console.warn("⚠️ Could not extract provider ID from reference:", ref);
        return null;
    }

    return fetchProvider(providerId, fhirClient, store, options);
};

export async function getCircleOfCare(patientId, fhirClient) {
    if (!patientId) {
        throw new Error("Patient ID is required to fetch circle of care.");
    }

    try {
        // Run queries in parallel
        const [
            careTeamPractitioners,
            relatedPractitioners,
            orgPractitioners,
            communicationPractitioners
        ] = await Promise.all([
            fetchCareTeamPractitioners(patientId, fhirClient),
            fetchRelatedPersonPractitioners(patientId, fhirClient),
            fetchOrganizationsPractitioners(patientId, fhirClient),
            fetchCommunicationSenders(patientId, fhirClient)
        ]);

        // Merge and deduplicate by ID
        const all = [
            ...careTeamPractitioners,
            ...relatedPractitioners,
            ...orgPractitioners,
            ...communicationPractitioners
        ];

        const deduped = Object.values(
            all.reduce((acc, p) => {
                if (p?.id) acc[p.id] = p;
                return acc;
            }, {})
        );

        console.log(careTeamPractitioners);

        return deduped;
    } catch (err) {
        console.error("❌ Failed to get circle of care:", err);
        throw err;
    }
}



