// 4. Get Communication senders
export async function fetchCommunicationSenders(patientId, client, store) {
    console.log("Fetching communication senders for patient:", patientId);
    const bundle = await client.request(`Communication?subject=Patient/${patientId}`);
    const comms = bundle?.entry?.map((e) => e.resource) || [];

    const refs = comms
        .map((c) => c.sender?.reference)
        .filter((ref) => ref?.startsWith("Practitioner/"));

    const uniqueIds = [...new Set(refs.map((ref) => ref.split("/")[1]))];

    const practitioners = await Promise.all(
        uniqueIds.map((id) => fetchProvider(id, client, store))
    );

    console.log("Found practitioners from communications:", practitioners);
    return practitioners.filter(Boolean);
}


// 🔁 Utility: Deduplicated resolution of Practitioner references
export async function fetchPractitionersByRefs(refs, client) {
    const uniqueRefs = [...new Set(refs)];
    const practitioners = [];

    for (const ref of uniqueRefs) {
        try {
            const p = await client.request(ref);
            practitioners.push(p);
        } catch (err) {
            console.warn(`⚠️ Failed to fetch practitioner: ${ref}`, err);
        }
    }

    return practitioners;
}

/**
 * Search for providers (Practitioner resources) by a search term (name, family, or given).
 * Returns an array of matching Practitioner resources.
 * @param {string} searchTerm
 * @param {object} fhirClient
 * @returns {Promise<Array>}
 */
export async function searchProvidersByTerm(searchTerm, fhirClient) {
    if (!searchTerm || !fhirClient) return [];
    try {
        const bundle = await fhirClient.request(`Practitioner?name=${encodeURIComponent(searchTerm)}`);
        return bundle?.entry?.map(e => e.resource) || [];
    } catch (error) {
        console.error("Failed to search providers:", error);
        return [];
    }
}

// 1. Get CareTeam Practitioners
export async function fetchCareTeamPractitioners(patientId, client, store) {
    console.log("Fetching care team practitioners for patient:", patientId);
    const bundle = await client.request(`CareTeam?patient=Patient/${patientId}`);
    console.log(bundle);
    const teams = bundle?.entry?.map(e => e.resource) || [];

    const references = teams
        .flatMap(t =>
            t.participant
                ?.map(p => p.member?.reference)
                .filter(ref => ref?.startsWith("Practitioner/")) || []
        );

    console.log(references);

    const uniqueIds = [...new Set(references.map(ref => ref.split("/")[1]))];
    console.log(uniqueIds);
    const practitioners = await Promise.all(uniqueIds.map(id => fetchProvider(id, client)));
    console.log(practitioners);

    return practitioners.filter(Boolean);
}


/**
 * Fetch all CarePlans for a given CareTeam.
 * @param {string} careTeamId - The ID of the CareTeam resource.
 * @param {object} client - The FHIR client instance.
 * @returns {Promise<Array>} - Array of CarePlan resources.
 */
export async function fetchCarePlans(careTeamId, client) {
    if (!careTeamId || !client) return [];
    try {
        // Search for CarePlans where careTeam reference matches the given CareTeam ID
        const bundle = await client.request(`CarePlan?care-team=CareTeam/${careTeamId}`);
        return bundle?.entry?.map(e => e.resource) || [];
    } catch (error) {
        console.error(`Failed to fetch CarePlans for CareTeam/${careTeamId}:`, error);
        return [];
    }
}

/**
 * Fetch CarePlans for a given patient that involve a specific practitioner.
 * @param {string} patientId - The Patient ID.
 * @param {string} practitionerId - The Practitioner ID.
 * @param {object} client - The FHIR client instance.
 * @returns {Promise<Array>} - Array of CarePlan resources.
 */
export async function fetchCarePlansForPractitioner(patientId, practitionerId, client) {
    // 1. Get all CareTeams for the patient
    const teamBundle = await client.request(`CareTeam?patient=Patient/${patientId}`);
    console.log(teamBundle);
    const teams = teamBundle?.entry?.map(e => e.resource) || [];
    console.log(teams);

    // 2. Filter down to only CareTeams that include this Practitioner
    const matchingTeams = teams.filter(team =>
        team.participant?.some(p => p.member?.reference === `Practitioner/${practitionerId}`)
    );

    console.log(matchingTeams);

    // 3. Fetch CarePlans that reference these CareTeams
    const carePlans = [];
    for (const team of matchingTeams) {
        const bundle = await client.request(`CarePlan?care-team=CareTeam/${team.id}`);
        const plans = bundle?.entry?.map(e => e.resource) || [];
        carePlans.push(...plans);
    }

    console.log(carePlans);

    return carePlans;
}

/**
 * Fetch CareTeams that link BOTH:
 *   - A specific Patient
 *   - A specific Practitioner (provider)
 *
 * @param {string} patientId
 * @param {string} providerId
 * @param {object} client - FHIR client instance
 * @returns {Promise<Array>} Array of CareTeam resources
 */
export async function getCareTeamsForProviderAndPatient(patientId, providerId, fhirClient) {
    if (!patientId || !providerId) {
        console.warn("getCareTeamsForProviderAndPatient: missing patientId or providerId");
        return [];
    }
    if (!fhirClient) return [];

    try {
        // 1. Pull ALL CareTeams for the patient
        const bundle = await fhirClient.request(`CareTeam?patient=Patient/${patientId}`);
        const teams = bundle?.entry?.map(e => e.resource) || [];

        if (teams.length === 0) return [];

        const providerRef = `Practitioner/${providerId}`;

        // 2. Filter teams to only those that contain the provider as a participant
        const matchingTeams = teams.filter(team =>
            team.participant?.some(
                p => p.member?.reference === providerRef
            )
        );

        return matchingTeams;

    } catch (err) {
        console.error("❌ Failed to fetch CareTeams for provider & patient:", err);
        return [];
    }
}

export async function getCareTeamsForPatient(patientId, fhirClient) {
    if (!patientId) {
        console.warn("getCareTeamsForPatient: missing patientId");
        return [];
    }
    if (!fhirClient) return [];

    try {
        // 1. Pull ALL CareTeams for the patient
        const bundle = await fhirClient.request(`CareTeam?patient=Patient/${patientId}`);
        const teams = bundle?.entry?.map(e => e.resource) || [];

        if (teams.length === 0) return [];

        // 2. Return all teams as-is (no provider filter)
        return teams;

    } catch (err) {
        console.error("❌ Failed to fetch CareTeams for patient:", err);
        return [];
    }
}

/**
 * Fetch a single CareTeam by its ID
 * @param {string} careTeamId - The FHIR CareTeam ID
 * @param {object} fhirClient - The FHIR client instance
 * @returns {Promise<object|null>} - Returns the CareTeam resource or null if not found
 */
export async function getCareTeam(careTeamId, fhirClient) {
    if (!careTeamId) {
        console.warn("getCareTeam: missing careTeamId");
        return null;
    }
    if (!fhirClient) {
        console.warn("getCareTeam: missing fhirClient");
        return null;
    }

    try {
        const careTeam = await fhirClient.request(`CareTeam/${careTeamId}`);
        return careTeam || null;
    } catch (err) {
        console.error(`❌ Failed to fetch CareTeam/${careTeamId}:`, err);
        return null;
    }
}



